import{_ as s,o as t,c as a,ae as i}from"./chunks/framework.DQC_QtFV.js";const k=JSON.parse('{"title":"MCP client (OAuth)","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/mcp.md","filePath":"en/guide/mcp.md","lastUpdated":1793162416000}'),o={name:"en/guide/mcp.md"};function n(h,e,r,l,d,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="mcp-client-oauth" tabindex="-1">MCP client (OAuth) <a class="header-anchor" href="#mcp-client-oauth" aria-label="Permalink to &quot;MCP client (OAuth)&quot;">​</a></h1><p>The assistant can act as an MCP client, and an MCP server that authenticates over OAuth can register it by <strong>Client ID Metadata Document</strong> (CIMD): the <code>client_id</code> is the URL of a JSON document, and the authorization server fetches it to learn the client&#39;s redirect URIs and its name. The <code>client_id</code> has to be the exact URL the document was fetched from, so one document describes one console address.</p><p>The three ways below are in order of recommendation. The first two answer &quot;where does the document live&quot;; the third needs no published document at all.</p><h2 id="_1-a-worker-one-address-for-every-console-address-recommended" tabindex="-1">1. A Worker: one address for every console address (recommended) <a class="header-anchor" href="#_1-a-worker-one-address-for-every-console-address-recommended" aria-label="Permalink to &quot;1. A Worker: one address for every console address (recommended)&quot;">​</a></h2><p><a href="https://github.com/4fuu/personal-bot/tree/main/cimd-worker" target="_blank" rel="noreferrer"><code>cimd-worker/</code></a> holds a Cloudflare Worker that puts an id of your own and the console&#39;s address in the path:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://personal-bot-cimd.popoi.work/&lt;id&gt;/http/localhost:8080/mcp-client.json</span></span></code></pre></div><p>is the document for a console reached at <code>http://localhost:8080</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;client_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://personal-bot-cimd.popoi.work/&lt;id&gt;/http/localhost:8080/mcp-client.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;redirect_uris&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:8080/mcp/oauth/callback&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Build the URL from <strong>an id of your own</strong> and the address you open the console at: the id, the console&#39;s scheme, host and port, then <code>/mcp-client.json</code>. The console&#39;s callback path is fixed (<code>/mcp/oauth/callback</code>); only the origin varies, so the origin rides in the path.</p><ul><li>Make the id with <code>openssl rand -hex 16</code>: 16 to 64 characters, <code>A-Z a-z 0-9 _ -</code>, at least one letter and one digit.</li><li><strong>Keep using the same one afterwards</strong>: it is part of the <code>client_id</code> the MCP server registered, so a new id is a new client there.</li><li>Two people whose consoles sit at the same origin - both on <code>http://localhost:8080</code>, say - each pick their own id, or they would register the same <code>client_id</code>.</li><li>Any origin is served, loopback included; only malformed input - a bad scheme, a segment that is not a host, the wrong path, an id that breaks its rules - is refused with a 400.</li></ul><p>Deploy your own if you would rather not depend on the one above:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cimd-worker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLOUDFLARE_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> that</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> may</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Worker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>The Worker has no dependencies and no build step.</p><h2 id="_2-the-static-file-mcp-client-json-on-github-pages" tabindex="-1">2. The static file: mcp-client.json on GitHub Pages <a class="header-anchor" href="#_2-the-static-file-mcp-client-json-on-github-pages" aria-label="Permalink to &quot;2. The static file: mcp-client.json on GitHub Pages&quot;">​</a></h2><p>The repository ships that document as <a href="https://github.com/4fuu/personal-bot/blob/main/mcp-client.json" target="_blank" rel="noreferrer"><code>mcp-client.json</code></a>, and the docs site publishes it at the site root, so its address is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://4fuu.github.io/personal-bot/mcp-client.json</span></span></code></pre></div><p>Its content (<code>client_id</code> is the URL it is served from):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;client_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://4fuu.github.io/personal-bot/mcp-client.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;redirect_uris&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:8080/mcp/oauth/callback&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Assumption:</strong> you reach the console at <code>http://localhost:8080</code>. If you reach it at another address - a domain, a tunnel, another port - the static file is the wrong tool, because <code>client_id</code> has to be the exact URL the document is fetched from: either use the Worker above, or edit <code>redirect_uris</code> in your copy to match the address the browser used exactly, because the authorization server refuses a callback that does not match.</p><h2 id="_3-publishing-nothing-at-all" tabindex="-1">3. Publishing nothing at all <a class="header-anchor" href="#_3-publishing-nothing-at-all" aria-label="Permalink to &quot;3. Publishing nothing at all&quot;">​</a></h2><p>If you would rather not publish anything, the other two ways are both on the panel&#39;s <a href="./console/workspace.html">Workspace</a> page:</p><ul><li><strong>Dynamic client registration</strong> (<code>dynamic</code>), which the authorization server has to support.</li><li><strong>A client id and secret registered by hand</strong> (<code>static</code>) on the MCP server.</li></ul><h2 id="authorizing-in-the-console" tabindex="-1">Authorizing in the console <a class="header-anchor" href="#authorizing-in-the-console" aria-label="Permalink to &quot;Authorizing in the console&quot;">​</a></h2><p>All three ways hand you the same thing: a <code>client_id</code> (the Worker&#39;s URL, the Pages URL, or the pair you registered by hand). Then:</p><ol><li>Add or edit the MCP server on the <a href="./console/workspace.html">Workspace</a> page, pick OAuth for its auth and one of 元数据文档 / 动态注册 / 手工登记 for the client mode.</li><li>Press 授权: the panel opens the authorization server&#39;s URL with the redirect it computed - the browser&#39;s own origin, not the console server&#39;s <code>Host</code>, which differ behind a proxy.</li><li>The authorization server sends the browser back to the console&#39;s own <code>/mcp/oauth/callback</code>, the console hands the code to the bot, and the tokens land in the bot&#39;s store.</li></ol><p>The tokens stay on the bot&#39;s side and the browser never sees one; a stored refresh token counts too, so a server you authorized once keeps reading 已授权. A stdio server cannot be authorized this way - there is no browser inside the sandbox to come back to - and is refused with that reason.</p>`,26)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
